<?php
defined('ABSPATH')||exit;
add_action('init',function(){register_post_type('cy_property',['label'=>'Fikcyjne nieruchomości','public'=>true,'show_ui'=>true,'show_in_rest'=>true,'has_archive'=>true,'rewrite'=>['slug'=>'nieruchomosc'],'supports'=>['title','editor','thumbnail','excerpt','custom-fields']]);});
add_shortcode('cy_property_catalog',function(){
 $beds=isset($_GET['bedrooms'])?absint($_GET['bedrooms']):0;$args=['post_type'=>'cy_property','post_status'=>'publish','posts_per_page'=>12,'orderby'=>'ID','order'=>'ASC'];if(in_array($beds,[1,2,3],true))$args['meta_query']=[['key'=>'_cy_bedrooms','value'=>$beds,'compare'=>'=','type'=>'NUMERIC']];
 $q=new WP_Query($args);$html='<form class="cy-filter" action="'.esc_url(home_url('/')).'" method="get"><label for="cy-bedrooms">Sypialnie w fikcyjnym katalogu</label><select id="cy-bedrooms" name="bedrooms"><option value="0">Wszystkie</option>';foreach([1,2,3] as $n)$html.='<option value="'.$n.'"'.selected($beds,$n,false).'>'.$n.'</option>';$html.='</select><button type="submit">Filtruj natywne wpisy</button></form><p class="cy-result-count">Liczba fikcyjnych ofert: '.(int)$q->found_posts.'</p><div class="cy-grid">';
 while($q->have_posts()){$q->the_post();$id=get_the_ID();$html.='<article class="cy-card">'.get_the_post_thumbnail($id,'full').'<div class="cy-card-body"><p class="cy-kicker">Własna fikcyjna oferta / '.(int)get_post_meta($id,'_cy_bedrooms',true).' '.((int)get_post_meta($id,'_cy_bedrooms',true)===1?'sypialnia':'sypialnie').'</p><h2><a href="'.esc_url(get_permalink()).'">'.esc_html(get_the_title()).'</a></h2><p>'.esc_html(get_the_excerpt()).'</p><p class="cy-meta">'.esc_html(get_post_meta($id,'_cy_internal_area',true)).' m² wnętrza · taras '.esc_html(get_post_meta($id,'_cy_terrace_area',true)).' m²</p><a class="cy-button" href="'.esc_url(get_permalink()).'">Zobacz komplet danych</a></div></article>';}
 wp_reset_postdata();return $html.'</div>';
});
add_action('wp_head',function(){$id=get_queried_object_id();if(get_post_meta($id,'_cy_own_fiction',true))echo '<meta name="description" content="'.esc_attr(get_post_meta($id,'_cy_seo_description',true)).'">';});
add_filter('pre_get_document_title',function($title){$id=get_queried_object_id();return get_post_meta($id,'_cy_own_fiction',true)?get_post_meta($id,'_cy_seo_title',true):$title;});
add_action('add_meta_boxes',function($type,$post){if(!$post||!get_post_meta($post->ID,'_cy_own_fiction',true))return;add_meta_box('cy-source-data','Własne parametry i SEO — natywne metadane',function($post){wp_nonce_field('cy_own_meta_'.$post->ID,'cy_own_meta_nonce');foreach(['seo_title'=>'Tytuł SEO','seo_description'=>'Opis SEO','bedrooms'=>'Sypialnie','internal_area'=>'Wnętrze m²','terrace_area'=>'Taras m²'] as $key=>$label)echo '<p><label>'.esc_html($label).'<input class="widefat" name="cy_'.$key.'" value="'.esc_attr(get_post_meta($post->ID,'_cy_'.$key,true)).'"></label></p>';echo '<p>Własne fikcyjne dane. To nie jest oferta sprzedaży ani projekt klienta.</p>';},$type,'normal','high');},10,2);
add_action('save_post',function($id){if(!get_post_meta($id,'_cy_own_fiction',true)||wp_is_post_revision($id)||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)||!current_user_can('edit_post',$id)||empty($_POST['cy_own_meta_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cy_own_meta_nonce'])),'cy_own_meta_'.$id))return;foreach(['seo_title','seo_description','bedrooms','internal_area','terrace_area'] as $key)if(isset($_POST['cy_'.$key]))update_post_meta($id,'_cy_'.$key,sanitize_text_field(wp_unslash($_POST['cy_'.$key])));});
